mapper.select:


    and w.room_id = #{roomId}
    and w.workstation_type = #{workstationType}
    and r.room_type = #{roomType}
    and r.mentor_id = #{mentorId}
    and w.status = #{status}
    and a.student_id = #{studentId}
    and w.workstation_no like concat('%', #{workstationNo}, '%')

order by w.room_id, w.layout_row, w.layout_col, w.workstation_id
